INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 7, 'theory', 'Quiz: namespaces');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 0, 'Two processes show the same value in /proc/PID/ns/net, for example net:[4026531840]. What does that mean?', '["They have the same IP addresses", "They run as the same user", "They are in the same network namespace", "They share a parent process"]', 2, 'The number in brackets is the namespace''s inode number. An equal number means the same namespace; addresses, owner and parent have nothing to do with it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 1, 'Why is --fork usually added to unshare --pid?', '["The new PID namespace goes to children, not to the caller; with fork the program is a child and gets PID 1", "To run the command in the background", "To get root rights without sudo", "To mount a fresh /proc"]', 0, 'A process does not change its own PID namespace once created; only its children get the new one, so the program is started as a child. A fresh /proc comes from the separate --mount-proc flag.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 2, 'The file /proc/PID/uid_map contains the line “0 100000 65536”. What is the host UID of a process whose UID inside is 5?', '["5", "100000", "65541", "100005"]', 3, 'The range starts at 0 inside and 100000 outside, so offset 5 gives 100005. The number 65541 wrongly adds the range length.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 3, 'What happens to a namespace created by ip netns add red when it has no processes?', '["It is removed at once", "It stays: it is held by a file mounted in /var/run/netns", "It merges with the initial network namespace", "It turns into a PID namespace"]', 1, 'ip netns add mounts the /proc/self/ns/net link over a named file. That mount keeps the namespace alive. ip netns delete removes it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 4, 'A container is started with --pid=host. What is true?', '["It does not see the host''s processes", "Its network is shared with the host''s", "It sees the host''s processes, while the other namespaces stay separate unless other options change them", "Processes inside it are numbered from one"]', 2, 'The --pid=host option shares only the host''s PID namespace with the container. Network, mounts and the rest are set by other options, and numbering from one happens only in a new PID namespace.');
